subtopics.example:
// global context exists at start
function greet() { /* a new function context is created on each call */ }
greet();

function a(){ b(); }
function b(){ /* stack: global -> a -> b */ }
a();

sandbox.code:
console.log(greet());   // 'hi' — function declaration hoisted
console.log(x);         // undefined — var hoisted, not yet assigned

var x = 5;
function greet() { return 'hi'; }

console.log(x);         // 5 — assigned during execution phase

function first() {
  second();
}
function second() {
  console.log('stack so far:');
  console.trace(); // prints the call stack: second <- first <- (global)
  return 'done';
}

console.log(first === undefined ? '' : '');
first();
console.log('back at global, stack unwound');

// Overflows for large n: each call pushes a context
function sumToRecursive(n) {
  if (n === 0) return 0;
  return n + sumToRecursive(n - 1);
}

function sumTo(n) {
  // TODO: rewrite iteratively to avoid deep call stack
}

console.log(sumTo(100000)); // 5000050000 (recursive version would overflow)

solution.code:
function sumTo(n) {
  let total = 0;
  for (let i = 1; i <= n; i++) {
    total += i;
  }
  return total;
}

console.log(sumTo(100000)); // 5000050000

brokenCode.code:
function countdown(n) {
  console.log(n);
  countdown(n - 1); // no base case -> contexts pile up forever
}

countdown(5); // logs 5,4,3,2,1,0,-1,... then RangeError

solution.code:
function countdown(n) {
  if (n < 0) return; // base case stops the recursion
  console.log(n);
  countdown(n - 1);
}

countdown(5); // 5,4,3,2,1,0 then returns; stack unwinds

// Puzzle (logs undefined, then 20):
var value = 10;
function show() {
  console.log(value); // undefined: local `value` is hoisted, shadows outer
  var value = 20;
  console.log(value); // 20
}
show();

// Corrected to log 10 then 20 (no shadowing of the first read):
var v = 10;
function showFixed() {
  console.log(v);     // 10: reads outer via scope chain (no local var v)
  let local = 20;
  console.log(local); // 20
}
showFixed();
